namespace HyperLib.Core;

public static partial class WorkLandingTemplateCatalog
{
    /// <summary>Materialized only inside a destination project; reading the catalog never writes source files.</summary>
    public const string ComponentSource = """
        @namespace HyperLib.Work.Blocks
        @using HyperLib.Core
        @using HyperLib.Runtime
        @inject RendererContentClient Content
        @inject RendererOptions Options
        <section class="wle @Design" style="@Colors" data-work-landing="true">
            <div class="wle-inner">
                <header class="wle-top">
                    <a class="wle-wordmark" href="@HomeUrl" data-hyperlib-navigate="@HomeId">@if(IsAtlas){<span class="wle-mark" aria-hidden="true">✧</span>}<span>@Brand</span></a>
                    <nav class="wle-menu" aria-label="Work navigation"><a href="#@ContentsId">Contents <span aria-hidden="true">↓</span></a>@if(Items.Count>0){<a href="@PageUrl(Items[0].Id)" data-hyperlib-navigate="@Items[0].Id">Start reading <span aria-hidden="true">↗</span></a>}<a href="@LibraryUrl" data-hyperlib-navigate="@LibraryId">Library</a></nav>
                </header>
                <div class="wle-hero">
                    <div class="wle-introduction">
                        <p class="wle-eyebrow" data-field="eyebrow" data-placeholder="Eyebrow">@Context.Text("eyebrow")</p>
                        <h1 data-field="title" data-placeholder="Work title">@Title</h1>
                        <p class="wle-description" data-field="text" data-placeholder="Introduce this Work">@Context.Text("text")</p>
                        <div class="wle-actions">@if(Items.Count>0){<a class="wle-start" href="@PageUrl(Items[0].Id)" data-hyperlib-navigate="@Items[0].Id"><span data-field="startLabel">@Context.Text("startLabel","Start reading")</span><span aria-hidden="true">→</span></a>}<a class="wle-contents-link" href="#@ContentsId">View contents <span aria-hidden="true">↓</span></a></div>
                    </div>
                    <div class="wle-cover" aria-hidden="@(Cover.Length==0?"true":null)">
                        @if(Cover.Length>0){<img src="@Cover" alt="@Context.Text("coverAlt")" loading="lazy"/>}
                        else if(IsAtlas){<div class="wle-orbits"><span class="wle-orbit wle-orbit-one"></span><span class="wle-orbit wle-orbit-two"></span><span class="wle-orbit wle-orbit-three"></span><span class="wle-orbit-axis"></span><span class="wle-orbit-star">✦</span><span class="wle-orbit-caption">ATLAS<br/>UNIVERSALIS</span></div>}
                        else{<div class="wle-cover-shape"><span class="wle-cover-letter">@Initial</span><span class="wle-cover-line"></span><span class="wle-cover-dot"></span></div>}
                    </div>
                </div>
                <div class="wle-summary"><span><strong>@Items.Count</strong> @(Items.Count==1?"Page":"Pages") to explore</span><span>A reading path of your own</span><span class="wle-summary-end">@(IsAtlas?"KNOWLEDGE / CONNECTED":"READ / DISCOVER / RETURN")</span></div>
                <section class="wle-contents" id="@ContentsId" aria-labelledby="@HeadingId">
                    <div class="wle-contents-heading"><p class="wle-eyebrow">CONTENTS / THE WORK</p><h2 id="@HeadingId" data-field="contentsTitle">@Context.Text("contentsTitle","Explore this Work")</h2></div>
                    @if(Items.Count==0){<p class="wle-empty">Your Pages will appear here as you add them to this Work.</p>}
                    else{<ol class="wle-page-list">@for(var index=0;index<Items.Count;index++){var item=Items[index];<li><a class="wle-page-link" href="@PageUrl(item.Id)" data-hyperlib-navigate="@item.Id" data-work-page="@item.Id"><span class="wle-page-number">@((index+1).ToString("00"))</span><span class="wle-page-copy">@if(item.Group.Length>0){<span class="wle-page-group">@item.Group</span>}<span class="wle-page-title">@item.Title</span></span><span class="wle-page-arrow" aria-hidden="true">↗</span></a></li>}</ol>}
                </section>
                <footer class="wle-footer"><p data-field="footerText">@Context.Text("footerText")</p><a href="#@ContentsId">Back to contents <span aria-hidden="true">↑</span></a></footer>
            </div>
        </section>
        @code {
            [Parameter, EditorRequired] public BlockContext Context { get; set; } = default!;
            private sealed record PageEntry(string Id,string Title,string Group);
            private List<PageEntry> Items { get; set; }=[];
            private string WorkTitle {get;set;}="Your Work";
            private string HomeUrl {get;set;}="browse";
            private string HomeId {get;set;}="";
            private string LibraryId {get;set;}="library";
            private string LibraryUrl=>Options.GatewayUrl.TrimEnd('/')+"/#"+Uri.EscapeDataString(LibraryId);
            private string Brand => string.IsNullOrWhiteSpace(Context.Text("brand")) ? WorkTitle : Context.Text("brand");
            private string Title => string.IsNullOrWhiteSpace(Context.Text("title")) ? WorkTitle : Context.Text("title");
            private string Initial => Title.Trim().Length==0 ? "W" : System.Globalization.StringInfo.GetNextTextElement(Title.Trim()).ToUpperInvariant();
            private string Cover => Context.Text("cover");
            private string Design => Designs.Contains(Context.Text("design")) ? Context.Text("design") : "work-landing-editorial";
            private bool IsAtlas=>Design.StartsWith("atlas-",StringComparison.Ordinal);
            private string ContentsId=>"work-contents-"+Context.Id;
            private string HeadingId=>"work-contents-heading-"+Context.Id;
            private string Colors=>"--wle-bg:"+Color("backgroundColor","#f8f5ed")+";--wle-accent:"+Color("accentColor","#82523b")+";--wle-ink:"+Color("textColor","#272923")+";";
            private string Color(string key,string fallback)=>System.Text.RegularExpressions.Regex.IsMatch(Context.Text(key),"^#[a-fA-F0-9]{6}$")?Context.Text(key):fallback;
            private static string PageUrl(string id)=>"page/"+Uri.EscapeDataString(id);
            private static readonly HashSet<string> Designs=["work-landing-editorial","work-landing-directory","work-landing-handbook","work-landing-gallery","work-landing-course","work-landing-journal","work-landing-minimal","atlas-work-landing-observatory","atlas-work-landing-atlas","atlas-work-landing-archive"];
            protected override async Task OnParametersSetAsync()
            {
                var state=await Content.GetStateAsync();
                var work=state.Nodes.FirstOrDefault(node=>node.Id==Options.PackageId && node.Type=="work");
                WorkTitle=work?.Title??"Your Work";
                var landing=work?.Appearance.TryGetValue("workLandingPage",out var landingValue)==true?landingValue.GetString():null;
                HomeId=landing is {Length:>0}?landing:Options.PackageId;
                LibraryId=work?.ParentId??state.LibraryId;
                HomeUrl=landing is {Length:>0}?PageUrl(landing):"browse/"+Uri.EscapeDataString(Options.PackageId);
                var nodes=state.Nodes.Where(node=>node.WorkId==Options.PackageId).ToArray();
                var children=nodes.GroupBy(node=>node.ParentId??"").ToDictionary(group=>group.Key,group=>group.OrderBy(node=>node.Order).ThenBy(node=>node.Id,StringComparer.Ordinal).ToArray(),StringComparer.Ordinal);
                var visited=new HashSet<string>(StringComparer.Ordinal);
                var pages=new List<PageEntry>();
                void Walk(string parent,string group){if(!children.TryGetValue(parent,out var list))return;foreach(var node in list){if(!visited.Add(node.Id))continue;if(node.Type=="page"){if(node.Id!=landing)pages.Add(new(node.Id,node.Title,group));}else Walk(node.Id,group.Length==0?node.Title:group+" / "+node.Title);}}
                Walk(Options.PackageId,"");
                // Older libraries may contain orphaned hierarchy nodes; never silently hide a readable Work Page.
                foreach(var node in nodes.Where(node=>node.Type=="page" && node.Id!=landing && !visited.Contains(node.Id)).OrderBy(node=>node.Order).ThenBy(node=>node.Id,StringComparer.Ordinal))pages.Add(new(node.Id,node.Title,""));
                Items=pages;
            }
        }
        """;

    public const string ComponentCss = """
        .wle{position:relative;isolation:isolate;overflow:hidden;background:var(--wle-bg);color:var(--wle-ink);font-family:system-ui,sans-serif;line-height:1.6;border-radius:2px;box-sizing:border-box;min-width:0}
        .wle *{box-sizing:border-box}.wle a{color:inherit;text-decoration:none}.wle a:focus-visible{outline:3px solid var(--wle-accent);outline-offset:5px}.wle-inner{position:relative;z-index:1;max-width:1260px;margin:auto;padding:0 clamp(24px,6vw,88px)}
        .wle-top{display:flex;align-items:center;justify-content:space-between;gap:28px;padding:27px 0;border-bottom:1px solid color-mix(in srgb,var(--wle-ink) 20%,transparent)}.wle-wordmark{font-weight:650;font-size:14px;display:flex;gap:10px;align-items:center;max-width:50%;overflow-wrap:anywhere}.wle-mark{font-size:29px;line-height:1;color:var(--wle-accent)}.wle-menu{display:flex;flex-wrap:wrap;gap:25px;font-size:13px;font-weight:550}.wle-menu a:hover{color:var(--wle-accent)}
        .wle-hero{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);align-items:center;gap:48px;padding:76px 0 70px;min-height:480px}.wle-eyebrow{font:650 10px/1.8 system-ui,sans-serif;letter-spacing:.19em;text-transform:uppercase;color:var(--wle-accent);margin:0 0 19px}.wle h1{font:500 clamp(40px,6vw,80px)/1.02 Georgia,serif;letter-spacing:-.045em;margin:0;overflow-wrap:anywhere}.wle-description{font-size:clamp(15px,1.5vw,19px);line-height:1.75;max-width:610px;margin:26px 0 30px;color:color-mix(in srgb,var(--wle-ink) 78%,var(--wle-bg));white-space:pre-line}.wle-actions{display:flex;align-items:center;flex-wrap:wrap;gap:24px;margin-top:28px;font-size:13px;font-weight:650}.wle-start{display:inline-flex;gap:25px;padding:14px 21px;background:var(--wle-accent);color:var(--wle-bg)!important;border-radius:3px}.wle-start:hover{filter:brightness(1.1)}.wle-contents-link{border-bottom:1px solid color-mix(in srgb,var(--wle-ink) 40%,transparent);padding:9px 0}
        .wle-cover{width:100%;aspect-ratio:1;display:grid;place-items:center;min-width:0}.wle-cover img{width:100%;height:100%;object-fit:cover;display:block;border-radius:2px}.wle-cover-shape{position:relative;width:84%;height:84%;border:1px solid var(--wle-accent);display:grid;place-items:center;transform:rotate(-5deg);background:color-mix(in srgb,var(--wle-accent) 7%,var(--wle-bg))}.wle-cover-letter{font:400 clamp(100px,18vw,240px)/1 Georgia,serif;color:var(--wle-accent);transform:rotate(5deg)}.wle-cover-line{position:absolute;top:15%;bottom:15%;left:15%;right:15%;border-top:1px solid var(--wle-accent);border-bottom:1px solid var(--wle-accent);transform:rotate(45deg);opacity:.35}.wle-cover-dot{position:absolute;width:16%;height:16%;right:-8%;top:9%;border-radius:50%;background:var(--wle-accent)}
        .wle-summary{display:flex;gap:25px;flex-wrap:wrap;align-items:center;border-top:1px solid color-mix(in srgb,var(--wle-ink) 20%,transparent);border-bottom:1px solid color-mix(in srgb,var(--wle-ink) 20%,transparent);padding:20px 0;font-size:12px;color:color-mix(in srgb,var(--wle-ink) 72%,var(--wle-bg))}.wle-summary strong{color:var(--wle-ink);margin-right:4px}.wle-summary-end{margin-left:auto;font-size:9px;letter-spacing:.14em}.wle-contents{padding:54px 0 72px;scroll-margin-top:24px}.wle-contents-heading{margin-bottom:28px}.wle-contents-heading .wle-eyebrow{margin-bottom:9px}.wle h2{font:500 clamp(26px,3vw,38px)/1.2 Georgia,serif;margin:0;letter-spacing:-.03em}.wle-page-list{list-style:none;padding:0;margin:0;border-top:1px solid color-mix(in srgb,var(--wle-ink) 20%,transparent)}.wle-page-list li{margin:0;border-bottom:1px solid color-mix(in srgb,var(--wle-ink) 20%,transparent)}.wle-page-link{display:flex;align-items:center;gap:24px;padding:23px 4px;min-height:78px;transition:background .15s,color .15s}.wle-page-link:hover{background:color-mix(in srgb,var(--wle-accent) 8%,transparent);color:var(--wle-accent)}.wle-page-number{font:500 11px/1.5 system-ui,sans-serif;letter-spacing:.1em;color:var(--wle-accent);min-width:22px}.wle-page-copy{display:flex;flex-direction:column;gap:3px;min-width:0}.wle-page-title{font:500 22px/1.35 Georgia,serif;overflow-wrap:anywhere}.wle-page-group{font:500 10px/1.5 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.08em;color:color-mix(in srgb,var(--wle-ink) 65%,var(--wle-bg));overflow-wrap:anywhere}.wle-page-arrow{margin-left:auto;font-size:22px;color:var(--wle-accent)}.wle-empty{padding:30px 0;border-top:1px solid color-mix(in srgb,var(--wle-ink) 20%,transparent);font-size:14px;color:color-mix(in srgb,var(--wle-ink) 68%,var(--wle-bg))}.wle-footer{border-top:1px solid color-mix(in srgb,var(--wle-ink) 20%,transparent);display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:27px 0 30px;font-size:11px}.wle-footer p{margin:0}.wle-footer a{color:var(--wle-accent)}
        .work-landing-directory .wle-page-list,.work-landing-course .wle-page-list,.atlas-work-landing-atlas .wle-page-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;border:0}.work-landing-directory .wle-page-list li,.work-landing-course .wle-page-list li,.atlas-work-landing-atlas .wle-page-list li{border:1px solid color-mix(in srgb,var(--wle-ink) 18%,transparent);background:color-mix(in srgb,var(--wle-bg) 75%,white 25%);border-radius:6px}.work-landing-directory .wle-page-link,.work-landing-course .wle-page-link,.atlas-work-landing-atlas .wle-page-link{padding:24px 20px;min-height:110px}.work-landing-directory h1{font-family:system-ui,sans-serif;font-weight:650;letter-spacing:-.06em}.work-landing-directory .wle-cover-shape{border-radius:50%;transform:none;background:var(--wle-accent)}.work-landing-directory .wle-cover-letter{color:var(--wle-bg);transform:none}.work-landing-directory .wle-cover-line{border-color:var(--wle-bg)}.work-landing-directory .wle-cover-dot{background:var(--wle-bg);border:1px solid var(--wle-accent)}
