        .work-landing-course .wle-cover-shape{transform:rotate(4deg);border-radius:18px;background:linear-gradient(145deg,color-mix(in srgb,var(--wle-accent) 18%,var(--wle-bg)),var(--wle-bg))}.work-landing-course .wle-cover-letter{transform:rotate(-4deg);font-style:italic}.work-landing-course .wle-page-number{border:1px solid color-mix(in srgb,var(--wle-accent) 40%,transparent);width:38px;height:38px;border-radius:50%;display:grid;place-items:center;flex-shrink:0}.work-landing-course .wle-start{border-radius:30px}.work-landing-course .wle-page-title{font-family:system-ui,sans-serif;font-size:17px}.work-landing-course .wle-page-list li{border-radius:12px}
