g-atlas .wle-orbit-caption{transform:rotate(12deg)}.atlas-work-landing-archive .wle-hero{grid-template-columns:1fr;min-height:0;padding:65px 0 55px}.atlas-work-landing-archive .wle-cover{display:none}.atlas-work-landing-archive .wle-top,.atlas-work-landing-archive .wle-footer{border-color:var(--wle-accent)}.atlas-work-landing-archive .wle-introduction{max-width:850px}.atlas-work-landing-archive .wle-contents{display:grid;grid-template-columns:.55fr 1fr;gap:55px}.atlas-work-landing-archive .wle-page-link{padding:27px 0}.atlas-work-landing-archive .wle-page-number{font-family:Georgia,serif;font-size:15px}
